package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

public class TarUtils_parseOctal_TriageGen0Test {

    @Test
    public void testParseOctal_ValidSimple() {
        byte[] buffer = "000123 ".getBytes();
        // length 7: "000123 "
        // ends with space, end becomes 6.
        // loop from 0 to 6.
        long result = TarUtils.parseOctal(buffer, 0, 7);
        assertEquals(83L, result); // 123 octal is 83 decimal
    }

    @Test
    public void testParseOctal_ValidWithLeadingSpaces() {
        byte[] buffer = "   0755 ".getBytes();
        // length 8: "   0755 "
        // skip spaces: start becomes 3
        // trailer is space: end becomes 7
        // end-1 is '5', not space/null. Wait, logic says:
        // trailer = buffer[end-1] (index 7 is ' '). end becomes 7.
        // trailer = buffer[end-1] (index 6 is '5'). end stays 7.
        // start 3, end 7. buffer[3..6] is "0755"
        long result = TarUtils.parseOctal(buffer, 0, 8);
        assertEquals(493L, result); // 755 octal
    }

    @Test
    public void testParseOctal_ValidWithNullTrailer() {
        byte[] buffer = new byte[10];
        buffer[0] = '0';
        buffer[1] = '1';
        buffer[2] = 0; // NUL
        buffer[3] = 0; // NUL
        // length 4: "01\0\0"
        // trailer = buffer[3] (0). end becomes 3.
        // trailer = buffer[2] (0). end becomes 2.
        // loop 0 to 2: "01"
        long result = TarUtils.parseOctal(buffer, 0, 4);
        assertEquals(1L, result);
    }

    @Test
    public void testParseOctal_StartsWithZero() {
        byte[] buffer = new byte[5];
        buffer[0] = 0;
        buffer[1] = '1';
        // if buffer[start] == 0 return 0L
        assertEquals(0L, TarUtils.parseOctal(buffer, 0, 5));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_LengthTooShort() {
        byte[] buffer = "1".getBytes();
        TarUtils.parseOctal(buffer, 0, 1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidTrailer() {
        byte[] buffer = "01234A".getBytes();
        // 'A' is not space or 0
        TarUtils.parseOctal(buffer, 0, 6);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidDigit() {
        byte[] buffer = "0128 ".getBytes(); // '8' is invalid octal
        TarUtils.parseOctal(buffer, 0, 5);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidDigitNegative() {
        byte[] buffer = "012- ".getBytes();
        TarUtils.parseOctal(buffer, 0, 5);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidDigitTooHigh() {
        byte[] buffer = "0129 ".getBytes();
        TarUtils.parseOctal(buffer, 0, 5);
    }

    @Test
    public void testParseOctal_OffsetUsage() {
        byte[] buffer = "XYZ 010 ".getBytes();
        // offset 4, length 5 -> " 010 "
        // start skips space -> start=5
        // trailer is space -> end=8-1=7
        // trailer is 0 at index 7? No, let's be precise.
        // buffer[4]=' ', [5]='0', [6]='1', [7]='0', [8]=' '
        // length 5, offset 4. end = 9.
        // trailer = buffer[8] (' '). end becomes 8.
        // trailer = buffer[7] ('0'). end stays 8.
        // start=5, end=8. buffer[5,6,7] is "010"
        long result = TarUtils.parseOctal(buffer, 4, 5);
        assertEquals(8L, result);
    }

    @Test
    public void testParseOctal_MultipleTrailingSpaces() {
        byte[] buffer = "012  ".getBytes(); // "012" + space + space
        // length 5. end = 5.
        // trailer = buffer[4] (' '). end becomes 4.
        // trailer = buffer[3] (' '). end becomes 3.
        // start 0, end 3. "012"
        long result = TarUtils.parseOctal(buffer, 0, 5);
        assertEquals(10L, result);
    }
}
